cat > src/claim-office.spec.ts <<'EOF'
import { describe, it } from "vitest";

describe("MHPCO quote -- base premiums", () => {
  it.todo("charges only the 5 G processing fee for an empty item list -- premium 5 G");
  it.todo("charges a sword at base premium 100 G -- premium 115 G (100 + 10 first insurance + 5 fee)");
  it.todo("charges an amulet at base premium 60 G -- premium 71 G (60 + 6 first insurance + 5 fee)");
  it.todo("charges a staff at base premium 80 G -- premium 93 G (80 + 8 first insurance + 5 fee)");
  it.todo("charges a potion at base premium 40 G -- premium 49 G (40 + 4 first insurance + 5 fee)");
  it.todo("charges a rune at base premium 25 G -- premium 31 G (25 + 2.5 first insurance + 5 fee, rounded up)");
  it.todo("charges a moonstone at base premium 25 G -- premium 31 G (25 + 2.5 first insurance + 5 fee, rounded up)");
});

describe("MHPCO quote -- component building blocks", () => {
  it.todo("charges 2 runes at base premium 50 G (no block)");
  it.todo("charges 3 runes at base premium 60 G (block applies)");
  it.todo("charges 4 runes at base premium 100 G (no block -- block requires exactly 3)");
  it.todo("charges 7 runes at base premium 175 G (no block -- block requires exactly 3)");
  it.todo("charges 2 runes + 1 moonstone at base premium 75 G (no block: alike means same type)");
  it.todo("charges 3 runes + 3 moonstones at base premium 120 G (two separate blocks)");
});

describe("MHPCO quote -- item modifiers", () => {
  it.todo("adds a 50 % curse surcharge to the cursed item's base premium -- cursed sword base 100 G -> 150 G");
  it.todo("adds a 30 % high-enchantment surcharge at exactly enchantment 5 -- sword base 100 G -> 130 G");
  it.todo("adds no high-enchantment surcharge at enchantment 4 -- sword base premium stays 100 G");
  it.todo("adds both surcharges for a cursed sword with enchantment 5 -- base 100 G -> 180 G");
  it.todo("applies the curse surcharge only to the cursed item -- cursed sword + plain amulet -> 210 G before policy modifiers and fee");
});

describe("MHPCO quote -- policy-wide modifiers", () => {
  it.todo("applies the 20 % loyalty discount at exactly 2 years with MHPCO");
  it.todo("applies no loyalty discount at 1 year with MHPCO");
  it.todo("applies the 10 % first-insurance surcharge to the policy base premium of every quote");
  it.todo("applies a 15 % follow-up discount to each contract after the customer's first quote");
  it.todo("applies no follow-up discount to the customer's first quote");
  it.todo("adds the 5 G processing fee at the very end, after all percentage modifiers");
});

describe("MHPCO quote -- rounding in the MHPCO's favor", () => {
  it.todo("rounds a premium of 197.5 G up to 198 G");
  it.todo("keeps intermediate amounts as fractions and rounds only the final premium");
});

describe("MHPCO quote -- integration examples", () => {
  it.todo("quotes 165 G for a newcomer's cursed steel sword at enchantment 3 (0 years, first contract)");
  it.todo("quotes 160 G for a 3-year customer's second contract covering a cursed sword at enchantment 7");
});

describe("MHPCO quote -- rejections", () => {
  it.todo("rejects a quote containing an unknown item type (e.g. broomstick) by throwing an Error");
});

describe("MHPCO claim -- standard reimbursement and deductible", () => {
  it.todo("pays 400 G for a regular steel sword at enchantment 3 with damage 500 G (500 - 100 deductible)");
  it.todo("pays 100 G for a damaged rune with damage 200 G (no enchantment or material, 200 - 100)");
  it.todo("applies the 100 G deductible once per damaged item -- sword 500 G + amulet 300 G -> payout 600 G");
  it.todo("pays 0 G rather than a negative payout when damage is below the 100 G deductible");
});

describe("MHPCO claim -- special clauses", () => {
  it.todo("reimburses 50 % for damage to an item with exactly enchantment 8 -- steel sword, damage 1000 G -> payout 400 G");
  it.todo("reimburses 50 % for damage at enchantment 9 -- steel sword, damage 1000 G -> payout 400 G");
  it.todo("fully reimburses dragon-material damage -- dragon sword at enchantment 5, damage 800 G -> payout 700 G");
  it.todo("lets the 50 % enchantment rule win over dragon material -- dragon sword at enchantment 9, damage 1000 G -> payout 400 G");
  it.todo("applies the 50 % enchantment rule at exactly enchantment 8 on dragon material -- damage 1000 G -> payout 400 G");
});

describe("MHPCO claim -- insurance sum and cap", () => {
  it.todo("caps a sword policy at 2000 G (2 x insurance sum 1000 G)");
  it.todo("sums insurance values across items -- sword + amulet -> insurance sum 1600 G, cap 3200 G");
  it.todo("bases the cap on unmodified insurance values -- cursed sword (premium 165 G) -> cap 2000 G");
  it.todo("excludes the block discount from the insurance sum -- sword + 3 runes -> insurance sum 1750 G, cap 3500 G");
  it.todo("counts each item of a repeated type -- two swords -> insurance sum 2000 G, cap 4000 G");
  it.todo("reports remainingCap after a claim -- sword policy, claim 1500 G -> payout 1400 G, remainingCap 600 G");
  it.todo("reduces a later payout to the remaining cap -- second claim of 1500 G -> payout 600 G, remainingCap 0 G");
});

describe("MHPCO claim -- repeated item types", () => {
  it.todo("treats two sword damage entries on a two-sword policy as separate damages with their own deductibles");
  it.todo("rejects more damage entries of a type than the policy covers (two sword damages, one sword insured) by throwing an Error");
});

describe("MHPCO claim -- rejections", () => {
  it.todo("rejects a damage entry whose item is not part of the policy (amulet damaged, only a sword insured) by throwing an Error");
  it.todo("rejects a damage entry with an unknown item type by throwing an Error");
  it.todo("rejects a damage entry with a negative amount (-200) by throwing an Error");
});

describe("MHPCO claim -- rounding in the MHPCO's favor", () => {
  it.todo("rounds a payout of 350.5 G down to 350 G");
});

describe("MHPCO scenario runner", () => {
  it.todo("returns one result per step in input order");
  it.todo("lets a claim step reference the policy created by an earlier quote step via its zero-based index");
  it.todo("runs the schema example scenario -- amulet quote for a 5-year customer, then a 200 G fire claim");
  it.todo("rejects a claim step referencing a step index that is not a quote by throwing an Error");
});

describe("claim-office CLI", () => {
  it.todo("reads a scenario from stdin and writes {results: [...]} as JSON to stdout with exit code 0");
  it.todo("exits non-zero and writes an error description to stderr for an unknown item type, writing no results to stdout");
  it.todo("exits non-zero and writes an error description to stderr for a damage entry outside the policy");
  it.todo("exits non-zero and writes an error description to stderr for a negative damage amount");
});
EOF
